WITH ranked AS (
  SELECT `groupName`, `totalSnatched`, RANK() OVER (ORDER BY `totalSnatched` DESC) AS rnk
  FROM `workspace`.`kaggledbqa_whatcdhiphop`.`torrents`
  WHERE `groupName` ILIKE '%houston%' AND `groupName` IS NOT NULL AND `totalSnatched` IS NOT NULL
)
SELECT `groupName` FROM ranked WHERE rnk = 1;
